    /**
     * @method
     * @name kalshi#fetchMarkets
     * @description fetches kalshi markets; with a query it resolves the query via the events endpoint and returns the matched events' markets, otherwise it pages the markets listing
     * @see https://trading-api.readme.io/reference/getmarkets
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.query] a single search query; resolved against the events endpoint (event title/ticker), then the matched events' markets are returned
     * @param {string[]} [params.queries] multiple search queries (alternative to query); markets from any matching event are returned
     * @param {int} [params.limit] for an unscoped listing (no query), the max number of markets to collect (defaults to options.maxFetchMarketsLimit, 1000)
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> queries = this.parseSearchQueries(parameters);
        int queriesLength = (queries?.Count ?? 0);
        // kalshi's public markets endpoint has no free-text search, so a query would otherwise
        // force a client-side scan of every open market (thousands, paged 1000 at a time, which
        // hangs). Resolve the query against the events endpoint instead — it is bounded by
        // maxPages, scoped server-side, supports multiple topics, and returns each event's parsed
        // markets — then flatten those markets.
        if (queriesLength > 0)
        {
            object eventParams = this.omit(parameters, new List<object>() {"limit"});
            List<object> events = ccxt.BaseExchange.FromPredictionEventList(await this.FetchEvents(eventParams));
            int eventsLength = (events?.Count ?? 0);
            List<object> queryMarkets = new List<object>() {};
            for (int ei = 0; ei < eventsLength; ei++)
            {
                List<object> eventMarkets = this.safeList((events != null && ei < events.Count ? events[ei] : null), "markets", new List<object>() {});
                int eventMarketsLength = eventMarkets.Count;
                for (int mi = 0; mi < eventMarketsLength; mi++)
                {
                    queryMarkets.Add((eventMarkets != null && mi < eventMarkets.Count ? eventMarkets[mi] : null));
                }
            }
            return ccxt.BaseExchange.ToMarketInterfaceList(queryMarkets);
        }
        object rest = this.omit(parameters, new List<object>() {"query", "queries", "limit"});
        // no query: page the markets listing directly. Cap the total collected so an unscoped
        // loadMarkets cannot run away through every kalshi market via the cursor.
        Int64? maxMarkets = this.safeInteger(parameters, "limit", this.safeInteger(this.options, "maxFetchMarketsLimit", 1000));
        List<object> flatMarkets = new List<object>() {};
        Dictionary<string, object> eventsDict = new Dictionary<string, object>() {};
        string? cursor = null;
        // don't request a full 1000-market page (3+ MB) when the caller wants fewer
        Int64? pageLimit = this.safeInteger(this.options, "marketsPageLimit", 1000);
        Int64? limit = ((Int64?)mathMin(maxMarkets, pageLimit));
        // default to tradeable (open) markets; kalshi has thousands of closed/settled markets and
        // an unfiltered cursor pages through those, so loadMarkets would otherwise return mostly
        // closed markets. Pass params.status (e.g. 'closed', 'settled', 'unopened') to override
        string? status = this.safeString(rest, "status", "open");
        while (true)
        {
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "limit", limit },
                { "status", status },
            };
            if ((cursor != null))
            {
                request["cursor"] = cursor;
            }
            Dictionary<string, object> response = await this.kalshiPublicGetMarkets(this.extend(request, rest));
            List<object> rawMarkets = this.safeList(response, "markets", new List<object>() {});
            int rawMarketsLength = rawMarkets.Count;
            for (int i = 0; i < rawMarkets.Count; i++)
            {
                object raw = rawMarkets[i];
                List<object> parsed = this.parseBinaryMarketToOutcomes(raw);
                string? eventTicker = this.safeString(raw, "event_ticker");
                string? eventTitle = this.safeString(raw, "title", eventTicker);
                string? eventKey = null;
                if ((eventTitle != null) && eventTitle != "")
                {
                    eventKey = this.shortenSlug(eventTitle);
                }
                for (int j = 0; j < (parsed?.Count ?? 0); j++)
                {
                    object m = parsed[j];
                    flatMarkets.Add(m);
                    if (((eventKey != null)) && (eventKey != ""))
                    {
                        if (!(((eventKey != null) && (eventsDict?.ContainsKey(eventKey) == true))))
                        {
                            eventsDict[(string)eventKey] = new Dictionary<string, object>() {
                                { "id", eventTicker },
                                { "slug", eventTicker },
                                { "event", eventKey },
                                { "title", eventTitle },
                                { "markets", new List<object>() {} },
                            };
                        }
                        object eventEntry = getValue(eventsDict, eventKey);
                        // push through a local and write the slice back — the go transpiler's
                        // AppendToArray reassigns only a local copy of a map-stored array, so a
                        // direct push on eventEntry['markets'] loses the element in go
                        object entryMarkets = getValue(eventEntry, "markets");
                        ((IList<object>)entryMarkets).Add(m);
                        ((IDictionary<string,object>)eventEntry)["markets"] = entryMarkets;
                    }
                }
            }
            cursor = this.safeString(response, "cursor");
            int collectedLength = (flatMarkets?.Count ?? 0);
            if (((cursor == null) || cursor == "") || (rawMarketsLength < limit) || (maxMarkets == null || collectedLength >= maxMarkets))
            {
                break;
            }
        }
        this.events = eventsDict;
        int flatMarketsLength = (flatMarkets?.Count ?? 0);
        if (((maxMarkets == null || flatMarketsLength > maxMarkets)))
        {
            return ccxt.BaseExchange.ToMarketInterfaceList(this.arraySlice(flatMarkets, 0, maxMarkets));
        }
        return ccxt.BaseExchange.ToMarketInterfaceList(flatMarkets);
    }

    public virtual List<object> parseBinaryMarketToOutcomes(object raw)
    {
        return new List<object> {this.parseMarket(raw)};
    }

    /**
     * @ignore
     * @method
     * @name kalshi#fetchOutcome
     * @description resolves a single outcome on demand instead of bulk-loading. kalshi has tens of
     * thousands of markets, so an id-form miss fetches just the requested market by ticker, and a
     * handle-form miss resolves through the series-scoped events listing (a handle's first token is
     * its series ticker); both merge into the cache so repeat lookups are free
     * @param {string} outcomeSymbol an outcome id — a kalshi ticker, or a ticker with a '-NO' suffix — or a unified handle like KXBTCD_26JUL1417_53_000_ABOVE:YES
     * @returns {object} the resolved outcome object
     */
    public async override Task<Dictionary<string, object>> FetchOutcome(object outcomeSymbol)
    {
        // a kalshi ticker never contains ':', so only id-form inputs can be fetched by ticker —
        // sending a unified handle (EVENT_MARKET:LABEL) as a ticker is a guaranteed 404.
        // the indexOf comparison must stay INLINE and `< 0` — the php transpiler only rewrites the
        // inline form to mb_strpos's `=== false`; assigned to a variable first, absence (false)
        // never satisfies `< 0` and id-form inputs take the wrong branch
        if (((string)outcomeSymbol).IndexOf(":", StringComparison.Ordinal) < 0)
        {
            // parseToInt-wrapped .length: the bare `const n = str.length;` statement is the php
            // transpiler's ARRAY hint (count()), and `.length` inline inside slice() args breaks
            // the python transpiler — this form emits strlen()/len() correctly in both
            Int64? symbolLength = this.parseToInt(((string)outcomeSymbol).Length);
            string? suffix = slice(outcomeSymbol, subtract(symbolLength, 3), null);
            bool isNo = (suffix == "-NO");
            object baseTicker = outcomeSymbol;
            if (isNo)
            {
                baseTicker = slice(outcomeSymbol, 0, subtract(symbolLength, 3));
            }
            Dictionary<string, object> response = null;
            try
            {
                response = await this.kalshiPublicGetMarketsTicker(new Dictionary<string, object>() {
                    { "ticker", baseTicker },
                });
            } catch(Exception e)
            {
                // an unknown ticker returns 'not_found', which handleErrors maps to BadSymbol —
                // fall through to the search-driven base resolution; let network failures propagate
                if (!(e is BadSymbol))
                {
                    throw e;
                }
                response = null;
            }
            if ((response != null))
            {
                IDictionary<string, object> rawMarket = this.safeDict(response, "market", response);
                Dictionary<string, object> parsed = this.parseMarket(rawMarket);
                if ((this.markets == null))
                {
                    this.markets = this.createSafeDictionary();
                }
                if ((parsed == null))
                {
                    throw new ExchangeError ((this.id + " fetchOutcome() could not resolve parsed")) ;
                }
                ((IDictionary<string,object>)this.markets)[(string)(parsed != null && parsed.ContainsKey("market") ? parsed["market"] : null)] = parsed;
                // index only the market just fetched, not a full O(markets x outcomes) rebuild of the
                // whole cache — on-demand fetchOutcome (loadAllOutcomes false) is the hot path here
                this.indexMarketOutcomes(parsed);
                return ccxt.BaseExchange.ToDict(this.outcome(outcomeSymbol));
            }
        } else
        {
            // handle-form: handles are shortenSlug(event_ticker) + '_' + <market slug> and kalshi
            // series tickers are single alphanumeric segments, so the handle's first '_' token is
            // its series ticker — fetch that series' open events (server-side filter, one page in
            // the common case) and re-check the cache for the exact handle
            List<object> handleParts = ((string)outcomeSymbol).Split(new [] {":"}, StringSplitOptions.None).ToList<object>();
            string? marketPart = this.safeString(handleParts, 0, "");
            List<object> parts = marketPart.Split(new [] {"_"}, StringSplitOptions.None).ToList<object>();
            string? seriesTicker = this.safeString(parts, 0);
            if (((seriesTicker != null)) && (seriesTicker != ""))
            {
                try
                {
                    ccxt.BaseExchange.FromPredictionEventList(await this.FetchEvents(new Dictionary<string, object>() { { "series_ticker", seriesTicker }, }));
                } catch(Exception e)
                {
                    // an unknown series is a plain miss — the free-text fallback below still runs;
                    // let network failures propagate
                    if (!(e is BadSymbol))
                    {
                        throw e;
                    }
                }
                if (this.hasOutcome(outcomeSymbol))
                {
                    return ccxt.BaseExchange.ToDict(this.safeOutcome(outcomeSymbol));
                }
            }
        }
        // free-text fallback: the base derives a search query from the handle's words, resolves it
        // through fetchEvents({query}) and re-checks the cache, throwing a guidance-rich BadSymbol
        // on a genuine miss
        return ccxt.BaseExchange.ToDict(await base.FetchOutcome(outcomeSymbol));
    }

    /**
     * @ignore
     * @method
     * @name kalshi#fetchOutcomes
     * @description resolves several uncached outcomes at once — ticker-shaped ids are batched through the markets listing's tickers filter (100 per request); anything left unresolved (handle-shaped symbols, unknown tickers) falls back to the single fetch and its guidance-rich BadSymbol
     * @see https://docs.kalshi.com/api-reference/market/get-markets
     * @param {string[]} outcomeSymbols kalshi tickers (optionally with a '-NO' suffix) or outcome handles
     * @returns {object} the outcome cache
     */
    public async override Task<Dictionary<string, object>> FetchOutcomes(object outcomeSymbols)
    {
        List<object> tickers = new List<object>() {};
        Dictionary<string, object> seen = new Dictionary<string, object>() {};
        for (int i = 0; i < getArrayLength(outcomeSymbols); i++)
        {
            object outcomeSymbol = getValue(outcomeSymbols, i);
            if (getIndexOf(outcomeSymbol, ":") >= 0)
            {
                continue;
            }
            // parseToInt-wrapped .length — see the fetchOutcome comment (php count()/python slice traps)
            Int64? symbolLength = this.parseToInt(((string)outcomeSymbol).Length);
            string? suffix = slice(outcomeSymbol, subtract(symbolLength, 3), null);
            object baseTicker = outcomeSymbol;
            if (suffix == "-NO")
            {
                baseTicker = slice(outcomeSymbol, 0, subtract(symbolLength, 3));
            }
            if (!((baseTicker is string inOpKey0 && seen.ContainsKey(inOpKey0))))
            {
                seen[(string)baseTicker] = true;
                tickers.Add(baseTicker);
            }
        }
        if ((this.markets == null))
        {
            this.markets = this.createSafeDictionary();
        }
        Int64? chunkSize = this.safeInteger(this.options, "fetchOutcomesBatchSize", 100);
        int tickersLength = (tickers?.Count ?? 0);
        object startIndex = 0;
        while (isLessThan(startIndex, tickersLength))
        {
            object endIndex = this.sum(startIndex, chunkSize);
            if (isGreaterThan(endIndex, tickersLength))
            {
                endIndex = tickersLength;
            }
            List<object> chunk = new List<object>() {};
            for (object i = startIndex; isLessThan(i, endIndex); postFixIncrement(ref i))
            {
                chunk.Add(getValue(tickers, i));
            }
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "tickers", String.Join(",", chunk.ToArray()) },
                { "limit", chunkSize },
            };
            Dictionary<string, object> response = await this.kalshiPublicGetMarkets(request);
            List<object> rawMarkets = this.safeList(response, "markets", new List<object>() {});
            for (int i = 0; i < rawMarkets.Count; i++)
            {
                Dictionary<string, object> parsed = this.parseMarket(rawMarkets[i]);
                if ((parsed == null))
                {
                    throw new ExchangeError ((this.id + " fetchOutcomes() could not resolve parsed")) ;
                }
                ((IDictionary<string,object>)this.markets)[(string)(parsed != null && parsed.ContainsKey("market") ? parsed["market"] : null)] = parsed;
                this.indexMarketOutcomes(parsed);
            }
            startIndex = this.sum(startIndex, chunkSize);
        }
        for (int i = 0; i < getArrayLength(outcomeSymbols); i++)
        {
            if (!this.hasOutcome(getValue(outcomeSymbols, i)))
            {
                ccxt.BaseExchange.FromDict(await this.FetchOutcome(getValue(outcomeSymbols, i)));
            }
        }
        return ccxt.BaseExchange.ToDict(this.outcomes);
    }

    public override object handleErrors(object code, string reason, string url, string method, object headers, object body, object response, Dictionary<string, object> requestHeaders, object requestBody)
    {
        // kalshi returns { "error": { "code": "...", ... } } with a 4xx; map known codes to ccxt
        // errors (e.g. not_found -> BadSymbol) so callers can distinguish them from a transport
        // outage (the base otherwise maps a bare 404 to the exchange-not-available error). unmapped codes fall
        // through to the base http-status handling.
        if (((response == null)) || ((response == null)))
        {
            return null;
        }
        IDictionary<string, object> error = this.safeDict(response, "error");
        if ((error != null))
        {
            string? errorCode = this.safeString(error, "code");
            string feedback = ((this.id + " ") + (body));
            this.throwExactlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("exact") ? ((IDictionary<string, object>)this.exceptions)["exact"] : null), errorCode, feedback);
            this.throwBroadlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("broad") ? ((IDictionary<string, object>)this.exceptions)["broad"] : null), errorCode, feedback);
        }
        // a 400 is a client-side bad request (bad params, invalid order), not a transport outage —
        // throw BadRequest instead of letting the base map the bare 400 to a retryable network-unavailable error
        if (isEqual(code, 400))
        {
            string feedback = ((this.id + " ") + (body));
            throw new BadRequest (feedback) ;
        }
        return null;
    }

    public override object calculateFee(string? symbol, string? type, string? side, double? amount, double? price, object takerOrMaker = null, object parameters = null)
    {
        // kalshi's trading fee is NOT a flat 7% — it is 0.07 * contracts * price * (1 - price), which
        // peaks at price 0.5 and vanishes near 0 or 1. the describe() `taker: 0.07` is only the
        // coefficient; compute the real per-contract formula here so fee estimates are accurate
        takerOrMaker ??= "taker";
        parameters ??= new Dictionary<string, object>();
        string? priceStr = this.numberToString(price);
        string? amountStr = this.numberToString(amount);
        string? oneMinusP = Precise.stringSub("1", priceStr);
        string? feeCost = Precise.stringMul("0.07", amountStr);
        feeCost = Precise.stringMul(feeCost, priceStr);
        feeCost = Precise.stringMul(feeCost, oneMinusP);
        return new Dictionary<string, object>() {
            { "type", takerOrMaker },
            { "currency", "USD" },
            { "rate", 0.07 },
            { "cost", this.parseNumber(feeCost) },
        };
    }

    public override Dictionary<string, object> parseMarket(object raw)
    {
        // {
        //    "can_close_early":true,
        //    "close_time":"2029-07-01T14:00:00Z",
        //    "created_time":"0001-01-01T00:00:00Z",
        //    "early_close_condition":"This market will close and expire early if the event occurs.",
        //    "event_ticker":"KXBALANCE-29",
        //    "expected_expiration_time":"2029-07-01T14:00:00Z",
        //    "expiration_time":"2029-07-01T14:00:00Z",
        //    "expiration_value":"",
        //    "fractional_trading_enabled":false,
        //    "last_price_dollars":"0.1100",
        //    "latest_expiration_time":"2029-07-01T14:00:00Z",
        //    "liquidity_dollars":"0.0000",
        //    "market_type":"binary",
        //    "no_ask_dollars":"0.9000",
        //    "no_bid_dollars":"0.8900",
        //    "no_sub_title":"During Trump's term",
        //    "notional_value_dollars":"1.0000",
        //    "open_interest_fp":"16353.00",
        //    "open_time":"2025-01-03T15:00:00Z",
        //    "previous_price_dollars":"0.0000",
        //    "previous_yes_ask_dollars":"0.0000",
        //    "previous_yes_bid_dollars":"0.0000",
        //    "price_level_structure":"linear_cent",
        //    "price_ranges":[
        //        {
        //            "end":"1.0000",
        //            "start":"0.0000",
        //            "step":"0.0100"
        //        }
        //    ],
        //    "response_price_units":"usd_cent",
        //    "result":"",
        //    "rules_primary":"If there is not a budget deficit for any of fiscal years 2025, 2026, 2027, or 2028, then the market resolves to Yes.",
        //    "rules_secondary":"",
        //    "settlement_timer_seconds":"1800",
        //    "status":"active",
        //    "subtitle":"",
        //    "tick_size":"1",
        //    "ticker":"KXBALANCE-29",
        //    "title":"Will Trump balance the budget?",
        //    "updated_time":"0001-01-01T00:00:00Z",
        //    "volume_24h_fp":"85.00",
        //    "volume_fp":"40208.00",
        //    "yes_ask_dollars":"0.1100",
        //    "yes_ask_size_fp":"",
        //    "yes_bid_dollars":"0.1000",
        //    "yes_bid_size_fp":"",
        //    "yes_sub_title":"During Trump's term"
        // }
        object ticker = this.safeString(raw, "ticker");
        string? eventTicker = this.safeString(raw, "event_ticker");
        string? subtitle = this.safeString(raw, "subtitle", this.safeString(raw, "title"));
        // markets use status 'active' while events use 'open'
        string? status = this.safeString(raw, "status");
        bool active = (status == "active") || (status == "open");
        // resolution: kalshi sets `result` to 'yes'/'no' once the market settles (empty while trading)
        string? result = this.safeStringLower(raw, "result");
        bool resolved = (status == "settled") || (((result != null)) && (result != ""));
        string? endDate = this.safeString(raw, "expiration_time");
        double? volume = this.safeNumber2(raw, "volume_fp", "volume");
        double? liquidity = this.safeNumber2(raw, "liquidity_dollars", "liquidity");
        double? openInt = this.safeNumber2(raw, "open_interest_fp", "open_interest");
        // Derive series ticker: drop last hyphen-segment from event_ticker
        List<object> eventParts = new List<object>() {};
        if (((eventTicker != null)) && (eventTicker != ""))
        {
            eventParts = eventTicker.Split(new [] {"-"}, StringSplitOptions.None).ToList<object>();
        }
        string? seriesTicker = eventTicker;
        int eventPartsLength = (eventParts?.Count ?? 0);
        if (eventPartsLength > 1)
        {
            List<object> seriesParts = ((List<object>)this.arraySlice(eventParts, 0, (eventPartsLength - 1)));
            seriesTicker = String.Join("-", seriesParts.ToArray());
        }
        // market symbol (no outcome suffix)
        object subtitleOrTicker = ticker;
        if ((subtitle != null))
        {
            subtitleOrTicker = subtitle;
        }
        string? marketSymbol = this.slugToMarketSymbol(eventTicker, subtitleOrTicker);
        // kalshi exposes the per-market price tick via price_ranges[].step (a dollar value,
        // e.g. "0.0010" for deci-cent markets, "0.0100" for cent markets); older responses
        // used tick_size (in cents). amount is a whole number of contracts
        List<object> priceRanges = this.safeList(raw, "price_ranges", new List<object>() {});
        IDictionary<string, object> firstRange = this.safeDict(priceRanges, 0, new Dictionary<string, object>() {});
        string? stepDollars = this.safeString(firstRange, "step");
        double? pricePrecision = this.parseNumber(Precise.stringDiv(this.safeString(raw, "tick_size", "1"), "100"));
        if ((stepDollars != null))
        {
            pricePrecision = this.parseNumber(stepDollars);
        }
        Dictionary<string, object> precision = new Dictionary<string, object>() {
            { "amount", 1 },
            { "price", pricePrecision },
        };
        // Build outcomes
        List<object> outcomeLabels = new List<object>() {"YES", "NO"};
        List<object> outcomeIds = new List<object>() {ticker, add(ticker, "-NO")};
        List<object> outcomes = new List<object>() {};
        string? resolvedOutcome = null;
        for (int oi = 0; oi < (outcomeLabels?.Count ?? 0); oi++)
        {
            string? label = ((string)outcomeLabels[oi]);
            string? outcomeHandle = this.slugToOutcomeSymbol(eventTicker, subtitleOrTicker, label);
            bool? winnerRaw = null;
            int? settleFractionRaw = null;
            if (resolved && ((result != null)) && (result != ""))
            {
                winnerRaw = ((label.ToLower() == result));
                settleFractionRaw = winnerRaw == true ? 1 : 0;
                if ((winnerRaw == true))
                {
                    resolvedOutcome = outcomeHandle;
                }
            }
            // effectively-final copies for the object literal below (Java cannot capture a
            // reassigned local into the anonymous inner class it emits for a map literal)
            bool? winner = winnerRaw;
            int? settleFraction = settleFractionRaw;
            outcomes.Add(new Dictionary<string, object>() {
                { "id", (outcomeIds != null && oi < outcomeIds.Count ? outcomeIds[oi] : null) },
                { "outcomeId", (outcomeIds != null && oi < outcomeIds.Count ? outcomeIds[oi] : null) },
                { "outcome", outcomeHandle },
                { "market", marketSymbol },
                { "label", label },
                { "active", active },
                { "winner", winner },
                { "settleFraction", settleFraction },
                { "precision", precision },
                { "info", new Dictionary<string, object>() {
                    { "ticker", ticker },
                    { "eventTicker", eventTicker },
                    { "seriesTicker", seriesTicker },
                    { "subtitle", subtitle },
                    { "outcomeLabel", label },
                    { "volume", volume },
                    { "liquidity", liquidity },
                    { "openInterest", openInt },
                } },
            });
        }
        // effectively-final copy for the market object literal below (reassigned in the loop)
        string? marketResolvedOutcome = resolvedOutcome;
        return ccxt.BaseExchange.ToDict(new Dictionary<string, object>() {
            { "id", ticker },
            { "market", marketSymbol },
            { "base", "USD" },
            { "quote", "USD" },
            { "settle", null },
            { "baseId", ticker },
            { "quoteId", "USD" },
            { "settleId", null },
            { "type", "prediction" },
            { "marketType", "binary" },
            { "executionModel", "clob" },
            { "spot", false },
            { "margin", false },
            { "swap", false },
            { "future", false },
            { "option", false },
            { "prediction", true },
            { "active", active },
            { "resolved", resolved },
            { "resolvedOutcome", marketResolvedOutcome },
            { "contract", false },
            { "linear", null },
            { "inverse", null },
            { "contractSize", null },
            { "expiry", ((endDate != null) && endDate != "") ? this.parse8601(endDate) : null },
            { "expiryDatetime", endDate },
            { "strike", null },
            { "optionType", null },
            { "taker", 0.07 },
            { "maker", 0 },
            { "percentage", true },
            { "tierBased", false },
            { "feeSide", "get" },
            { "precision", precision },
            { "limits", new Dictionary<string, object>() {
                { "leverage", new Dictionary<string, object>() {
                    { "min", 1 },
                    { "max", 1 },
                } },
                { "amount", new Dictionary<string, object>() {
                    { "min", 1 },
                    { "max", null },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", 0.01 },
                    { "max", 0.99 },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
            } },
            { "outcomes", outcomes },
            { "info", this.extend(raw, new Dictionary<string, object>() {
                { "ticker", ticker },
                { "eventTicker", eventTicker },
                { "seriesTicker", seriesTicker },
                { "subtitle", subtitle },
                { "volume", volume },
                { "liquidity", liquidity },
                { "openInterest", openInt },
            }) },
            { "created", null },
        });
    }

    /**
     * @method
     * @name kalshi#fetchTicker
     * @description fetches the current market price and bid/ask for a single kalshi outcome
     * @see https://docs.kalshi.com/api-reference/market/get-market
     * @param {string} outcome the unified outcome like TRUMP_BRING_BACK_MANUFACTURING:YES or outcomeId like KXGDPSHAREMANU-29
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
     */
    public async override Task<ccxt.PredictionTicker> FetchTicker(string outcome, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadOutcome(outcome);
        IDictionary<string, object> outcomeObj = this.outcome(outcome);
        string? ticker = this.safeString((outcomeObj != null && ((IDictionary<string, object>)outcomeObj).ContainsKey("info") ? ((IDictionary<string, object>)outcomeObj)["info"] : null), "ticker");
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "ticker", ticker },
        };
        Dictionary<string, object> response = await this.kalshiPublicGetMarketsTicker(this.extend(request, parameters));
        //
        //     {
        //         "market": {
        //             "can_close_early": true,
        //             "close_time": "2029-06-30T03:59:00Z",
        //             "created_time": "2025-06-05T17:55:43.779104Z",
        //             "early_close_condition": "This market will close and expire early if the event occurs.",
        //             "event_ticker": "KXGDPSHAREMANU-29",
        //             "expected_expiration_time": "2029-06-30T14:00:00Z",
        //             "expiration_time": "2029-07-07T14:00:00Z",
        //             "expiration_value": "",
        //             "floor_strike": "13.1",
        //             "fractional_trading_enabled": true,
        //             "last_price_dollars": "0.1980",
        //             "latest_expiration_time": "2029-07-07T14:00:00Z",
        //             "liquidity_dollars": "0.0000",
        //             "market_type": "binary",
        //             "no_ask_dollars": "0.8890",
        //             "no_bid_dollars": "0.8030",
        //             "no_sub_title": "Before 2029",
        //             "notional_value_dollars": "1.0000",
        //             "open_interest_fp": "11077.21",
        //             "open_time": "2025-06-05T18:00:00Z",
        //             "previous_price_dollars": "0.1980",
        //             "previous_yes_ask_dollars": "0.1970",
        //             "previous_yes_bid_dollars": "0.1110",
        //             "price_level_structure": "deci_cent",
        //             "price_ranges": [
        //                 {
        //                     "start": "0.55",
        //                     "end": "0.56",
        //                     "step": "0.01"
        //                 }
        //             ],
        //             "response_price_units": "usd_cent",
        //             "result": "",
        //             "rules_primary": "If the value added by Manufacturing to GDP in Q4 2028 is at least 13.1% (the value it was in Q1 2005), then the market resolves to Yes.",
        //             "rules_secondary": "",
        //             "settlement_timer_seconds": "1800",
        //             "status": "active",
        //             "strike_type": "greater_or_equal",
        //             "tick_size": "1",
        //             "ticker": "KXGDPSHAREMANU-29",
        //             "title": "Will Trump bring back manufacturing?",
        //             "updated_time": "2026-04-09T10:32:47.890506Z",
        //             "volume_24h_fp": "0.00",
        //             "volume_fp": "19617.68",
        //             "yes_ask_dollars": "0.1970",
        //             "yes_ask_size_fp": "2750.00",
        //             "yes_bid_dollars": "0.1110",
        //             "yes_bid_size_fp": "2505.61",
        //             "yes_sub_title": "Before 2029"
        //         }
        //     }
        //
        IDictionary<string, object> raw = ((IDictionary<string, object>)this.safeValue(response, "market", response));
        return ccxt.BaseExchange.ToPredictionTicker(this.parsePredictionTicker(raw, ((object)outcomeObj)));
    }

    /**
     * @method
